#!/usr/bin/env node

import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { pathToFileURL } from "node:url";

import { createProductionReleasePlan, projectRoot } from "./release-plan.mjs";

export async function generateSitesBootstrapPlan({ root = projectRoot } = {}) {
  const plan = await createProductionReleasePlan({ root });
  const outputPath = path.join(root, "worker/map-release-bootstrap-plan.ts");
  const contents = [
    "// Generated by scripts/production/generate-sites-bootstrap-plan.mjs. Do not edit by hand.",
    `export default ${JSON.stringify(plan)} as const;`,
    "",
  ].join("\n");
  const current = await readFile(outputPath, "utf8").catch(() => null);
  if (current !== contents) await writeFile(outputPath, contents, "utf8");
  return { outputPath, versionKey: plan.versionKey, objectCount: plan.objectCount };
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const result = await generateSitesBootstrapPlan();
  console.log(JSON.stringify(result, null, 2));
}
